/** City-wide band, for a district name the table does not know. */
export const LOT_RHYTHM_GLOBAL: LotRhythm = {
  p25: 2.26,
  p50: 3.15,
  p75: 4.62,
  runSize: 2,
  from: "citywide",
};

export function lotRhythmFor(district: string): LotRhythm {
  return SF_LOT_RHYTHM[district] ?? LOT_RHYTHM_GLOBAL;
}
